import java.util.*;

class Solution {
  public long maxPower(int[] stations, int r, int k) {
    int n = stations.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + stations[i];
    long[] initial = new long[n];
    long high = 0;
    for (int i = 0; i < n; i++) {
      initial[i] = prefix[Math.min(n, i + r + 1)] - prefix[Math.max(0, i - r)];
      high = Math.max(high, initial[i]);
    }
    long low = 0;
    high += k + 1L;
    while (low + 1 < high) {
      long middle = (low + high) >>> 1;
      if (canBuild(initial, n, r, k, middle)) low = middle;
      else high = middle;
    }
    return low;
  }

  private boolean canBuild(long[] initial, int n, int r, int k, long target) {
    long[] added = new long[n + 1];
    long active = 0, used = 0;
    for (int i = 0; i < n; i++) {
      active += added[i];
      long power = initial[i] + active;
      if (power < target) {
        long need = target - power;
        used += need;
        if (used > k) return false;
        active += need;
        added[Math.min(n, i + 2 * r + 1)] -= need;
      }
    }
    return true;
  }
}
